contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive contract and assert the owner's balance change after burn
    function run(uint256 initialSupply, string memory name, string memory symbol, uint256 mintToOwner, uint256 burnAmount) public {
        // Preconditions to make calls meaningful
        require(burnAmount <= initialSupply + mintToOwner, "burn <= supply+mint");

        // No state-changing call except those on c
        // We must set up the token so msg.sender of constructor of C is owner; the provided C already exists,
        // so we only interact with it. We'll assume c.owner() is the owner and that this test caller is owner.

        address owner = c.owner();

        // Ensure owner has enough balance to burn: if not, mint to owner using owner-only mintToken.
        uint256 ownerBalBefore = c.balanceOf(owner);

        if (ownerBalBefore < burnAmount) {
            // Only owner can call mintToken; this call must be performed by owner. We cannot change msg.sender here,
            // so require that this test contract is already the owner of c. If not, the verifier will avoid paths where it isn't.
            // To allow mint, require that this contract is the owner of c.
            require(owner == address(this), "test contract must be owner to mint");
            c.mintToken(owner, burnAmount - ownerBalBefore);
            ownerBalBefore = c.balanceOf(owner);
        }

        // Now call burn as owner (must be owner). Require test contract is owner.
        require(owner == address(this), "test contract must be owner to burn");

        // Perform the burn which changes state
        c.burn(burnAmount);

        uint256 ownerBalAfter = c.balanceOf(owner);

        // General rule: owner's balance decreased exactly by burnAmount
        assert(ownerBalAfter + burnAmount == ownerBalBefore);
    }

    // Minimal payable/fallback to accept potential ether if needed elsewhere
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // require caller is owner and has enough balance according to public getter
        address owner = c.owner();
        uint256 ownerBalance = c.balanceOf(owner);
        require(msg.sender == owner && ownerBalance >= value, "must be owner with enough balance");

        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }   // boundary

        // General rule: when caller is owner with sufficient balance, burn should not revert
        assert(reverted == false);
    }
    receive() external payable {}
}

