contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // require the caller (this test) to be the owner of c so we invoke burn as owner
        // The test contract must already be the owner in the deployed scenario; if not, the precondition fails and test is vacuously true
        // We only require a nonzero burn amount to expose the mutant's attempt to subtract from address(0)
        require(value > 0);
        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        // General rule: when totalSupply is at least value, owner-initiated burn should not revert.
        // Observe totalSupply via public getter and the revert flag.
        // Note: we do not read owner's balance (not necessary); original contract will succeed whenever totalSupply >= value and owner has sufficient balance.
        assert((c.totalSupply() < value) || (reverted == false));
    }
