pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzzed params: amount to burn and an address representing the caller (owner)
    function testFuzz_property(uint256 burnAmount, address caller) public {
        // Keep domain wide but ensure caller is non-zero and is the owner we will use
        vm.assume(caller != address(0));

        // The constructor created owner = msg.sender for c when deployed in setUp(); that owner is address(this) in the test
        // Make the test-owner hold some tokens so burn precondition can be satisfied when desired.
        // Mint tokens to the owner (address(this)) so owner has balance >= burnAmount for many fuzzed amounts
        // Bound burnAmount so it does not overflow totalSupply arithmetic here (totalSupply initially 0)
        uint256 bounded = bound(burnAmount, 0, type(uint128).max);

        // We need the test account (this contract) to be the owner; setUp deployed c from this contract so it is owner
        // Mint a large amount to owner so require(balance >= burnAmount) will pass for many fuzzed inputs
        c.mintToken(address(this), 1_000_000);

        // Record totalSupply and owner balance before burn
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeOwnerBal = c.balanceOf(address(this));

        // OnlyOwner: calls must come from owner (this contract). Call burn with bounded amount.
        bool ok;
        try c.burn(bounded) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read totalSupply and owner's balance via public getters
        uint256 afterTotal = c.totalSupply();
        uint256 afterOwnerBal = c.balanceOf(address(this));

        // The general rule (single assertion): if the burn call succeeded and the owner had enough balance before,
        // then in the correct contract totalSupply decreases by exactly bounded and owner's balance decreases by exactly bounded.
        // We assert the relationship between totalSupply delta and owner's balance delta by observing c's public getters.
        // This single assert is satisfied by the reference for all inputs, and the mutant (which subtracts from address(0))
        // will violate it for some inputs (owner balance unchanged while totalSupply changed vs expected).
        if (ok && beforeOwnerBal >= bounded) {
            assertTrue(afterTotal == beforeTotal - bounded && afterOwnerBal == beforeOwnerBal - bounded);
        } else {
            // If call did not succeed or precondition not met, the correct contract ensures no change in these values.
            assertTrue(afterTotal == beforeTotal && afterOwnerBal == beforeOwnerBal);
        }
    }
}

