pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // General rule to check (fuzzed): when the owner (deployer) calls burn(amount)
    // and has at least amount balance, totalSupply decreases by amount and the owner's
    // balance decreases by amount. The mutant subtracts from address(0) instead,
    // so there exist amounts for which owner's balance change != totalSupply change.
    function testFuzz_property(uint256 amount) public {
        // keep amount within reasonable wide bounds so initialSupply (0) scaled by decimals is 0
        // but we can mint tokens to owner to create balance. Use large bound to let fuzzer explore.
        uint256 boundedAmount = bound(amount, 0, type(uint128).max);

        // make the test deployer the owner and give it balance by minting
        // owner is deployer (address(this) in setUp during c construction)
        // mint some tokens to owner so they can burn
        uint256 mintAmount = boundedAmount;
        if (mintAmount == 0) {
            // ensure we still test a meaningful nonzero burn sometimes
            mintAmount = 1;
        }
        // only owner (this) can call mintToken; we are already the owner
        c.mintToken(address(this), mintAmount);

        // record pre-state
        uint256 preTotal = c.totalSupply();
        uint256 preOwnerBal = c.balanceOf(address(this));

        // ensure owner has at least boundedAmount so burn's require passes
        vm.assume(preOwnerBal >= boundedAmount);

        // call burn as owner (we are owner)
        bool ok;
        try c.burn(boundedAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference: burn should succeed (ok==true), and both totalSupply and owner's balance
        // should decrease by exactly boundedAmount. We assert the equality between the observed
        // decrease in totalSupply and the observed decrease in owner's balance. This holds for the
        // correct contract for all inputs; the mutant breaks it for some input because it subtracts
        // from address(0) instead of the owner.
        uint256 postTotal = c.totalSupply();
        uint256 postOwnerBal = c.balanceOf(address(this));

        // If burn reverted, then precondition (owner had sufficient balance) failed: but we assumed it holds.
        // So expect success.
        assertTrue(ok && (preTotal - postTotal == preOwnerBal - postOwnerBal));
    }
}

