contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function driving the contract and asserting the invariant distinguishing P from M.
    // Params:
    // - initialSupply: the initial total supply passed to C's constructor (not used here but required to choose a burnable amount)
    // - burnAmount: amount the owner will burn
    // This function assumes this test contract is the owner of c (i.e., deployed by the same address that created c) or that owner is msg.sender of c and equals address(this).
    function run(uint256 burnAmount) public {
        // Preconditions: caller must be the owner in C. We read owner via public getter.
        address owner = c.owner();
        require(owner == address(this), "this contract must be owner");

        // Read totalSupply before burn
        uint256 supply_before = c.totalSupply();
        // Read owner's balance before burn
        uint256 bal_before = c.balanceOf(address(this));

        // Require we have enough balance to burn the requested amount
        require(bal_before >= burnAmount, "insufficient balance to burn");

        // Perform the state-changing operation that differs between P and M
        bool ok = c.burn(burnAmount);
        require(ok, "burn failed");

        // Read totalSupply and balance after burn
        uint256 supply_after = c.totalSupply();
        uint256 bal_after = c.balanceOf(address(this));

        // The distinguishing rule: totalSupply decreased by exactly burnAmount while owner's balance decreased by burnAmount.
        // This holds in P (both decrease) and is violated in M (balance decreases but totalSupply does not).
        assert(supply_after + burnAmount == supply_before && bal_after + burnAmount == bal_before);
    }
}

