import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzz parameter: amount to burn. The owner (deployer) is the caller in setUp.
    function testFuzz_property(uint256 burnAmount) public {
        // Keep domain wide but avoid overflow nonsense when constructing initial balances:
        // c was deployed with initialSupply = 0, so owner balance == 0. We need owner to have >= burnAmount.
        // Mint some tokens to owner first. Bound the minted amount to a reasonable non-extreme range.
        uint256 minted = bound(burnAmount, 0, type(uint128).max);
        if (minted == 0) {
            // ensure at least 1 token so burn may be meaningful for some fuzz inputs
            minted = 1;
        }

        // owner is the test contract deployer (address(this) in setUp). call mintToken as owner.
        // No vm.prank needed because setUp deployed c from this contract.
        c.mintToken(address(this), minted);

        // Record totalSupply before burn
        uint256 before = c.totalSupply();

        // Ensure we only attempt to burn amounts that the owner actually has to make call succeed on reference
        uint256 toBurn = burnAmount;
        if (toBurn > c.balanceOf(address(this))) {
            // cap to current balance so the burn call will succeed
            toBurn = c.balanceOf(address(this));
        }

        // Call burn as owner (this contract)
        bool ok;
        try c.burn(toBurn) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted (shouldn't for admissible inputs), then totalSupply unchanged; we only assert when call succeeded.
        if (ok) {
            // For the correct contract: totalSupply == before - toBurn
            // For the mutant: totalSupply == before (bug) for some inputs. We assert the correct property that must hold.
            uint256 after = c.totalSupply();
            assertTrue(after == before - toBurn);
        }
    }
}

