        // bound amt to a reasonable range but allow zero too (we'll handle it)
        amt = bound(amt, 0, type(uint256).max);

        // make ownerAddr fundable and set as msg.sender for constructor-created owner emulation
        // We cannot change the actual owner of c after deployment; setUp deployed c from this test contract's address.
