        // If amt is zero, mint 1 so we can still assert behaviour for nonzero burns separately
        if (mintAmount == 0) {
            mintAmount = 1;
        }
        // mint tokens to this contract (this is allowed because this contract is the owner)
        c.mintToken(address(this), mintAmount);

        // record totalSupply before
