        uint256 ownerBalance = c.balanceOf(owner);
        uint256 oldTotal = c.totalSupply();

        require(burnAmount <= ownerBalance, "burnAmount must be <= owner balance");

        // perform the burn as owner by calling c.burn from this contract is only valid if this contract is the owner.
        // To satisfy the requirement without redeploying c, we require that this contract is the owner.
        // If this contract is not the owner the call will revert; that's acceptable for the verifier but must be avoided here.
