        // State-changing call that triggers the behavior difference
        c.burn(burnAmount);

        uint256 newTotal = c.totalSupply();

        // On the original contract P: newTotal == oldTotal - burnAmount
        // On mutant M: newTotal == oldTotal - 2*burnAmount, so the following assertion will fail for M.
        assert(newTotal == oldTotal - burnAmount);
    }

    // receive/fallback omitted
