        // No special precondition: owner may be msg.sender in the contract C, but we can only observe revert behavior.
        bool reverted; try c.burn(v) { reverted = false; } catch { reverted = true; }
        // If the call reverted, then the owner's balance must have been < v; if it didn't revert, owner's balance must have been >= v.
        // Observe owner's balance via the public getter `balanceOf(owner)` is not available directly, but C exposes balanceOf(address) as public mapping getter.
        // We can get owner via the public `owner()` getter.
        address ownerAddr = c.owner();
        uint256 ownerBal = c.balanceOf(ownerAddr);
        assert(reverted == (ownerBal < v));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // caller must be the owner to call burn (onlyOwner). Require that this contract is the owner.
        // We can only observe owner via c.owner() public getter.
        require(msg.sender == c.owner(), "test must be run by the owner");

        bool reverted;
        try c.burn(v) { reverted = false; } catch { reverted = true; }

        // If the call reverted, then the observable owner's balance must be < v.
        // Otherwise (not reverted) the owner's balance must be >= v.
        // We express this as: reverted == (c.balanceOf(c.owner()) < v)
        // Use the public getter balanceOf and owner.
        assert(reverted == (c.balanceOf(c.owner()) < v));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // precondition: caller is the contract owner (so msg.sender in C will be owner)
        // Achieve this by requiring that the test contract's address equals C.owner() so that when this test calls c.burn it will be from the owner address.
        // Note: c.owner() is a public getter returning address
        require(address(this) == c.owner());

        bool reverted;
        try c.burn(v) { reverted = false; } catch { reverted = true; }

        // The general rule: if the public getter balanceOf(owner) equals balanceOf(msg.sender) (they are the same address here), then the owner's burn should not revert in the original contract.
        // We observe only via public getters and the revert flag.
        assert(!(c.balanceOf(c.owner()) == c.balanceOf(address(this)) && reverted));
    }
    receive() external payable {}
}
